import { Group, Mesh, MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial, DirectionalLight, AmbientLight, PlaneGeometry, CylinderGeometry, OctahedronGeometry } from 'three/webgpu';
import { uv, mix, smoothstep, color, mul, add, vec3 } from 'three/tsl';
import { gsap } from 'gsap';
import { depthRotate } from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group: ThreeGroup } = ctx.THREE;
  const root = new ThreeGroup();

  // ---------- Backdrop Plane ----------
  const backdropGeom = new PlaneGeometry(7, 6);
  const bgUv = uv();

  const gradientNode = mix(
    mix(
      color('#0b0b10'),
      color('#12121a'),
      smoothstep(0.0, 0.6, bgUv.y)
    ),
    color('#16161d'),
    smoothstep(0.6, 1.0, bgUv.y)
  );

  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = gradientNode;
  backdropMat.transparent = false;

  const backdropMesh = new Mesh(backdropGeom, backdropMat);
  backdropMesh.position.set(0, 0, -2.5);
  root.add(backdropMesh);

  // ---------- Prism ----------
  const sideLength = 1.2;
  const prismRadius = sideLength / Math.sqrt(3); // inscribed circle radius
  const prismLength = 1.8;
  const prismGeom = new CylinderGeometry(prismRadius, prismRadius, prismLength, 3, 1, false);
  // orient along X axis
  prismGeom.rotateX(Math.PI / 2);
  // apply spec rotations
  prismGeom.rotateY(THREE.MathUtils.degToRad(20));
  prismGeom.rotateZ(THREE.MathUtils.degToRad(12));

  const prismMat = new MeshPhysicalNodeMaterial();
  prismMat.transmission = 1.0;
  prismMat.thickness = 0.9;
  prismMat.ior = 1.55;
  prismMat.roughness = 0.08;
  prismMat.clearcoat = 0.25;
  prismMat.clearcoatRoughness = 0.1;
  prismMat.attenuationColor = new THREE.Color('#e8ecf2');
  prismMat.attenuationDistance = 2.5;
  prismMat.iridescence = 1.0;
  prismMat.iridescenceIOR = 1.3;
  prismMat.iridescenceThicknessRange = [120, 480];
  // the dispersion effect is handled by the built‑in iridescence/ior blend

  const prismMesh = new Mesh(prismGeom, prismMat);
  root.add(prismMesh);

  // ---------- Emissive Core ----------
  const coreGeom = new OctahedronGeometry(0.35);
  const coreMat = new MeshStandardNodeMaterial();
  coreMat.emissiveNode = color('#ff2a38');
  coreMat.emissiveIntensity = 2.2;
  const coreMesh = new Mesh(coreGeom, coreMat);
  coreMesh.position.set(0, 0, 0);
  root.add(coreMesh);

  // ---------- Rim Light ----------
  const rimLight = new DirectionalLight('#a0cfff', 0.8);
  rimLight.position.set(-5, 0, 5);
  root.add(rimLight);

  // ---------- Ambient Light ----------
  const ambLight = new AmbientLight('#101017', 0.6);
  root.add(ambLight);

  // ---------- Caustic Streak ----------
  const causticGeom = new PlaneGeometry(2.4, 0.5);
  const causticUv = uv();

  const causticGrad = mix(
    mix(
      color('#ff2a38'),
      color('#e8ecf2'),
      smoothstep(0.2, 0.5, causticUv.x)
    ),
    color('#9fb0c4'),
    smoothstep(0.5, 0.8, causticUv.x)
  );

  const causticMat = new MeshBasicNodeMaterial();
  causticMat.colorNode = causticGrad;
  causticMat.transparent = true;
  causticMat.opacity = 0.35;

  const causticMesh = new Mesh(causticGeom, causticMat);
  causticMesh.rotation.x = -Math.PI / 2;
  causticMesh.position.set(0, -1.1, 0);
  root.add(causticMesh);

  // ---------- Text ----------
  const headlineItem = (config.textContent ?? config.intent?.visualSpec?.textContent ?? []).find(i => i.role === 'headline') || { text: "Light, machined.", typography: { fontSize: 68 } };
  const captionItem = (config.textContent ?? config.intent?.visualSpec?.textContent ?? []).find(i => i.role === 'caption') || { text: "SAPPHIRE OVER DIAL / ZERO DISTORTION", typography: { fontSize: 18 } };

  const headline = ctx.fontAtlas.createText(headlineItem.text, {
    fontSize: headlineItem.typography?.fontSize ?? 68,
    color: '#e8ecf2',
    align: 'center'
  });
  headline.position.set(0, -1.75, 0);
  root.add(headline);

  const caption = ctx.fontAtlas.createText(captionItem.text, {
    fontSize: captionItem.typography?.fontSize ?? 18,
    color: '#e8ecf2',
    align: 'center'
  });
  caption.position.set(0, -2.25, 0);
  root.add(caption);

  // ---------- Cinematic Primitive ----------
  const primitiveRefs = [];
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      if (prim.name === 'depth-rotate') {
        const ref = ctx.primitives['depth-rotate'](prismMesh, {
          maxDeg: prim.params?.maxDeg ?? 10
        });
        primitiveRefs.push(ref);
      } else {
        const ref = ctx.primitives[prim.name] && ctx.primitives[prim.name](root, prim.params);
        if (ref) primitiveRefs.push(ref);
      }
    }
  }

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // dispose geometries & materials
    [backdropGeom, prismGeom, coreGeom, causticGeom].forEach(g => g.dispose && g.dispose());
    [backdropMat, prismMat, coreMat, causticMat].forEach(m => m.dispose && m.dispose());

    // cleanup primitives
    primitiveRefs.forEach(r => r && typeof r.cleanup === 'function' && r.cleanup());

    // kill any GSAP timelines (none created here but defensive)
    gsap.globalTimeline.clear();
  };

  // handlers placeholder
  root.userData.handlers = {};

  return root;
}
